export { type ResendAdapterConfig, resend } from "./adapters/resend";
export { createMailer, type Mailer, type MailerConfig } from "./client";
export { EmailSendError, EmailValidationError } from "./errors";
export { type EmailFromKind, emailFrom } from "./from";
export { sendEmail } from "./send";
export {
  type CaptureEvent,
  capturePlugin,
  createEmailCaptureStore,
  type EmailCaptureStore,
} from "./plugins/capture";
export { type DefaultsOptions, defaultsPlugin } from "./plugins/defaults";
export {
  type EmailObservabilityEvent,
  type ObservabilityOptions,
  observabilityPlugin,
} from "./plugins/observability";
export { failingProvider, type MemoryAdapter, type MemoryRecord, memoryProvider } from "./testing";
export * from "./types";

export type MaybePromise<T> = T | Promise<T>;

export type EmailAddress = string | { email: string; name?: string };
export type EmailTag = { name: string; value: string };
export type EmailHeaders = Record<string, string>;
export type EmailMetadata = Record<string, string | number | boolean | null>;

export interface EmailAttachment {
  filename: string;
  content: string | Uint8Array;
  contentType?: string;
}

export interface EmailMessage {
  from: EmailAddress;
  to: EmailAddress | EmailAddress[];
  cc?: EmailAddress | EmailAddress[];
  bcc?: EmailAddress | EmailAddress[];
  replyTo?: EmailAddress | EmailAddress[];
  subject: string;
  html?: string;
  text?: string;
  headers?: EmailHeaders;
  tags?: EmailTag[];
  metadata?: EmailMetadata;
  attachments?: EmailAttachment[];
}

export interface SendOptions {
  idempotencyKey?: string;
  /** Send-scope metadata — flows to hooks, never to the provider. */
  metadata?: Record<string, unknown>;
}

/** Send options after defaults are merged; passed to adapters and hooks. */
export interface ResolvedSendOptions {
  idempotencyKey?: string;
  metadata: Record<string, unknown>;
}

export interface SendResult {
  /** Provider-native id. */
  id: string;
  provider: string;
  messageId: string;
}

export interface EmailAdapter {
  readonly name: string;
  send(message: EmailMessage, options: ResolvedSendOptions): Promise<SendResult>;
}

export interface BeforeSendContext {
  message: EmailMessage;
  options: ResolvedSendOptions;
}

export interface AfterSendEvent {
  provider: string;
  attempt: number;
  message: EmailMessage;
  options: ResolvedSendOptions;
  response: SendResult;
}

export interface RetryEvent {
  provider: string;
  attempt: number;
  nextAttempt: number;
  delayMs: number;
  error: Error;
  message: EmailMessage;
  options: ResolvedSendOptions;
}

export interface ErrorEvent {
  provider: string;
  attempt: number;
  error: Error;
  message: EmailMessage;
  options: ResolvedSendOptions;
}

export interface EmailPlugin {
  readonly id: string;
  /** Transform the message before validation/send. Return a new message to replace it. */
  beforeSend?(ctx: BeforeSendContext): MaybePromise<EmailMessage | undefined>;
  afterSend?(event: AfterSendEvent): MaybePromise<void>;
  onRetry?(event: RetryEvent): MaybePromise<void>;
  onError?(event: ErrorEvent): MaybePromise<void>;
}

/** Redacted message summary — safe for logs (no recipients, bodies, or values). */
export interface RedactedEmailMessage {
  subject: string;
  toCount: number;
  ccCount: number;
  bccCount: number;
  hasHtml: boolean;
  hasText: boolean;
  attachmentCount: number;
  tagNames: string[];
  metadataKeys: string[];
}

/** Thrown when a message is invalid or a route cannot represent a field. */
export class EmailValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EmailValidationError";
  }
}

/** Thrown when every adapter route fails after exhausting its retries. */
export class EmailSendError extends Error {
  readonly provider?: string;
  override readonly cause?: Error;
  constructor(message: string, options?: { provider?: string; cause?: Error }) {
    super(message);
    this.name = "EmailSendError";
    this.provider = options?.provider;
    this.cause = options?.cause;
  }
}

import { EmailSendError, EmailValidationError } from "./errors";
import type {
  EmailAdapter,
  EmailMessage,
  EmailPlugin,
  ResolvedSendOptions,
  SendOptions,
  SendResult,
} from "./types";

export interface MailerConfig {
  /** First adapter is primary; the rest are fallback routes, tried in order. */
  adapters: EmailAdapter[];
  plugins?: EmailPlugin[];
  /** Retries per adapter before falling back (default 2). */
  retries?: number;
  /** Backoff before each retry (default exponential, capped at 30s). */
  backoff?: (attempt: number) => number;
}

export interface Mailer {
  send(message: EmailMessage, options?: SendOptions): Promise<SendResult>;
}

const defaultBackoff = (attempt: number) => Math.min(1000 * 2 ** (attempt - 1), 30_000);

const sleep = (ms: number) =>
  ms > 0 ? new Promise((resolve) => setTimeout(resolve, ms)) : Promise.resolve();

function validateMessage(message: EmailMessage): void {
  if (!message.from) throw new EmailValidationError("`from` is required");
  if (!message.to || (Array.isArray(message.to) && message.to.length === 0)) {
    throw new EmailValidationError("`to` is required");
  }
  if (!message.subject) throw new EmailValidationError("`subject` is required");
  if (!message.html && !message.text) {
    throw new EmailValidationError("provide `html` or `text`");
  }
}

export function createMailer(config: MailerConfig): Mailer {
  const plugins = config.plugins ?? [];
  const retries = config.retries ?? 2;
  const backoff = config.backoff ?? defaultBackoff;

  // Observer hooks never block or break a send — failures are swallowed.
  async function notify<E>(
    pick: (plugin: EmailPlugin) => ((event: E) => unknown) | undefined,
    event: E,
  ): Promise<void> {
    await Promise.allSettled(
      plugins.map(async (plugin) => {
        const fn = pick(plugin);
        if (!fn) return;
        try {
          await fn.call(plugin, event);
        } catch {
          // a broken logger must not mask a provider failure
        }
      }),
    );
  }

  return {
    async send(message: EmailMessage, options: SendOptions = {}): Promise<SendResult> {
      if (config.adapters.length === 0) {
        throw new EmailSendError("no adapters configured");
      }

      const resolved: ResolvedSendOptions = {
        idempotencyKey: options.idempotencyKey,
        metadata: { ...options.metadata },
      };

      // beforeSend runs sequentially; each plugin may replace the message.
      let current = message;
      for (const plugin of plugins) {
        if (!plugin.beforeSend) continue;
        const next = await plugin.beforeSend({ message: current, options: resolved });
        if (next) current = next;
      }

      validateMessage(current);

      let lastError: Error | undefined;
      for (const adapter of config.adapters) {
        let attempt = 0;
        while (true) {
          attempt += 1;
          try {
            const response = await adapter.send(current, resolved);
            await notify((p) => p.afterSend, {
              provider: adapter.name,
              attempt,
              message: current,
              options: resolved,
              response,
            });
            return response;
          } catch (caught) {
            const error = caught instanceof Error ? caught : new Error(String(caught));
            lastError = error;

            // Validation errors are deterministic — retrying/falling back won't help.
            if (error instanceof EmailValidationError) throw error;

            if (attempt <= retries) {
              const delayMs = backoff(attempt);
              await notify((p) => p.onRetry, {
                provider: adapter.name,
                attempt,
                nextAttempt: attempt + 1,
                delayMs,
                error,
                message: current,
                options: resolved,
              });
              await sleep(delayMs);
              continue;
            }

            await notify((p) => p.onError, {
              provider: adapter.name,
              attempt,
              error,
              message: current,
              options: resolved,
            });
            break;
          }
        }
      }

      throw new EmailSendError("all email routes failed", {
        cause: lastError,
      });
    },
  };
}

import { resend } from "./adapters/resend";
import { createMailer, type Mailer } from "./client";
import { emailFrom } from "./from";
import type { EmailMessage, SendOptions, SendResult } from "./types";

// Lazy default mailer — Resend adapter built from the environment. Returns null
// (instead of throwing) when RESEND_API_KEY is absent, so builds never crash.
let cachedMailer: Mailer | null = null;
function getMailer(): Mailer | null {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) return null;
  if (!cachedMailer) cachedMailer = createMailer({ adapters: [resend({ apiKey })] });
  return cachedMailer;
}

type SendEmailInput = Omit<EmailMessage, "from"> & {
  from?: EmailMessage["from"];
};

/**
 * Convenience send for the common single-provider case. For defaults,
 * fallbacks, retries, or observability, build a mailer with `createMailer`.
 */
export async function sendEmail(
  input: SendEmailInput,
  options?: SendOptions,
): Promise<{ data: SendResult | null; error: Error | null }> {
  const mailer = getMailer();
  if (!mailer) {
    if (process.env.NODE_ENV === "production") {
      console.warn("RESEND_API_KEY is missing. Email not sent.");
    }
    return { data: null, error: new Error("RESEND_API_KEY is missing") };
  }

  try {
    const data = await mailer.send({ from: emailFrom("noreply"), ...input }, options);
    return { data, error: null };
  } catch (caught) {
    const error = caught instanceof Error ? caught : new Error(String(caught));
    return { data: null, error };
  }
}

/**
 * Single source for every outgoing sender address. Set `EMAIL_DOMAIN` and
 * verify that one domain with your provider (SPF + DKIM + DMARC) — all senders
 * then work. Edit the display names below to match your product.
 *
 * monitored = replies are read (support, security); noreply = transactional
 * default whose replies are not watched.
 */
const EMAIL_DOMAIN = process.env.EMAIL_DOMAIN || "example.com";

export type EmailFromKind = "noreply" | "support" | "security";

const REGISTRY: Record<EmailFromKind, { prefix: string; display: string }> = {
  noreply: { prefix: "noreply", display: "Acme" },
  support: { prefix: "support", display: "Acme Support" },
  security: { prefix: "security", display: "Acme Security" },
};

export function emailFrom(kind: EmailFromKind): string {
  const { prefix, display } = REGISTRY[kind];
  return `${display} <${prefix}@${EMAIL_DOMAIN}>`;
}

import { EmailValidationError } from "../errors";
import type {
  EmailAdapter,
  EmailAddress,
  EmailMessage,
  ResolvedSendOptions,
  SendResult,
} from "../types";

export interface ResendAdapterConfig {
  apiKey: string;
  /** Override the API origin, e.g. for a proxy. */
  baseUrl?: string;
  /** Custom fetch for tests or special runtimes. */
  fetch?: typeof fetch;
  /** Extra headers sent with every request. */
  headers?: Record<string, string>;
}

function formatAddress(address: EmailAddress): string {
  if (typeof address === "string") return address;
  return address.name ? `${address.name} <${address.email}>` : address.email;
}

function formatAddresses(address: EmailAddress | EmailAddress[]): string | string[] {
  return Array.isArray(address) ? address.map(formatAddress) : formatAddress(address);
}

function toPayload(message: EmailMessage): Record<string, unknown> {
  // Resend has no metadata concept — fail loudly instead of dropping it.
  if (message.metadata && Object.keys(message.metadata).length > 0) {
    throw new EmailValidationError("resend has no metadata field — use tags instead");
  }

  const payload: Record<string, unknown> = {
    from: formatAddress(message.from),
    to: formatAddresses(message.to),
    subject: message.subject,
  };
  if (message.html) payload.html = message.html;
  if (message.text) payload.text = message.text;
  if (message.cc) payload.cc = formatAddresses(message.cc);
  if (message.bcc) payload.bcc = formatAddresses(message.bcc);
  if (message.replyTo) payload.reply_to = formatAddresses(message.replyTo);
  if (message.headers) payload.headers = message.headers;
  if (message.tags) payload.tags = message.tags;
  if (message.attachments) {
    payload.attachments = message.attachments.map((a) => ({
      filename: a.filename,
      content: a.content,
      content_type: a.contentType,
    }));
  }
  return payload;
}

/** Resend adapter — calls the Resend Email API over `fetch` (no SDK dependency). */
export function resend(config: ResendAdapterConfig): EmailAdapter {
  const baseUrl = config.baseUrl ?? "https://api.resend.com";
  const doFetch = config.fetch ?? fetch;

  return {
    name: "resend",
    async send(message: EmailMessage, options: ResolvedSendOptions): Promise<SendResult> {
      const response = await doFetch(`${baseUrl}/emails`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${config.apiKey}`,
          "Content-Type": "application/json",
          ...(options.idempotencyKey ? { "Idempotency-Key": options.idempotencyKey } : {}),
          ...config.headers,
        },
        body: JSON.stringify(toPayload(message)),
      });

      if (!response.ok) {
        const detail = await response.text().catch(() => "");
        throw new Error(`resend: ${response.status} ${response.statusText} ${detail}`.trim());
      }

      const data = (await response.json()) as { id: string };
      return { id: data.id, provider: "resend", messageId: data.id };
    },
  };
}

import type { EmailAdapter, EmailMessage, ResolvedSendOptions, SendResult } from "./types";

export interface MemoryRecord {
  message: EmailMessage;
  options: ResolvedSendOptions;
}

export interface MemoryAdapter extends EmailAdapter {
  readonly sent: MemoryRecord[];
  clear(): void;
}

/** In-memory adapter — records sends and returns a fake id, no network. */
export function memoryProvider(): MemoryAdapter {
  const sent: MemoryRecord[] = [];
  let counter = 0;
  return {
    name: "memory",
    sent,
    clear() {
      sent.length = 0;
    },
    async send(message: EmailMessage, options: ResolvedSendOptions): Promise<SendResult> {
      sent.push({ message, options });
      counter += 1;
      const id = `mem_${counter}`;
      return { id, provider: "memory", messageId: id };
    },
  };
}

/** Adapter that fails its first `failTimes` attempts, then succeeds — for retry/fallback tests. */
export function failingProvider(options: { name?: string; failTimes?: number } = {}): EmailAdapter {
  const name = options.name ?? "failing";
  const failTimes = options.failTimes ?? Number.POSITIVE_INFINITY;
  let attempts = 0;
  return {
    name,
    async send(): Promise<SendResult> {
      attempts += 1;
      if (attempts <= failTimes) {
        throw new Error(`${name}: simulated failure ${attempts}`);
      }
      const id = `${name}_${attempts}`;
      return { id, provider: name, messageId: id };
    },
  };
}

import type {
  BeforeSendContext,
  EmailAddress,
  EmailHeaders,
  EmailMessage,
  EmailMetadata,
  EmailPlugin,
  EmailTag,
} from "../types";

export interface DefaultsOptions {
  id?: string;
  /** Default headers — merged under per-message headers (message wins). */
  headers?: EmailHeaders;
  /** Default tags — prepended before per-message tags. */
  tags?: EmailTag[];
  /** Default metadata — merged under per-message metadata (message wins). */
  metadata?: EmailMetadata;
  /** Default reply-to — used only when the message has none. */
  replyTo?: EmailAddress | EmailAddress[];
  /** Default idempotency key — used only when message/options have none. */
  idempotencyKey?: string;
  /** Prefix prepended to the key unless it already starts with it. */
  idempotencyKeyPrefix?: string;
}

/** Inject org-wide defaults into every message, with per-message override. */
export function defaultsPlugin(options: DefaultsOptions): EmailPlugin {
  return {
    id: options.id ?? "defaults",
    beforeSend(ctx: BeforeSendContext): EmailMessage {
      const message = ctx.message;

      const merged: EmailMessage = {
        ...message,
        headers: { ...options.headers, ...message.headers },
        tags: [...(options.tags ?? []), ...(message.tags ?? [])],
        metadata: { ...options.metadata, ...message.metadata },
        replyTo: message.replyTo ?? options.replyTo,
      };

      if (!ctx.options.idempotencyKey && options.idempotencyKey) {
        ctx.options.idempotencyKey = options.idempotencyKey;
      }
      const prefix = options.idempotencyKeyPrefix;
      const key = ctx.options.idempotencyKey;
      if (prefix && key && !key.startsWith(prefix)) {
        ctx.options.idempotencyKey = prefix + key;
      }

      return merged;
    },
  };
}

import type {
  AfterSendEvent,
  EmailMessage,
  EmailPlugin,
  ErrorEvent,
  MaybePromise,
  RedactedEmailMessage,
  RetryEvent,
} from "../types";

export type EmailObservabilityEvent = {
  type: "email.sent" | "email.retry" | "email.error";
  provider: string;
  attempt: number;
  metadata: Record<string, unknown>;
  message: RedactedEmailMessage;
  responseId?: string;
  messageId?: string;
  nextAttempt?: number;
  delayMs?: number;
  error?: { name: string; message: string };
};

export interface ObservabilityOptions {
  id?: string;
  log?: (event: EmailObservabilityEvent) => MaybePromise<void>;
  metric?: (event: EmailObservabilityEvent) => MaybePromise<void>;
  trace?: (event: EmailObservabilityEvent) => MaybePromise<void>;
  /** Replace the default redaction with your own summary shape. */
  redactMessage?: (message: EmailMessage) => RedactedEmailMessage;
}

function count(value: unknown): number {
  if (value === undefined || value === null) return 0;
  return Array.isArray(value) ? value.length : 1;
}

function defaultRedact(message: EmailMessage): RedactedEmailMessage {
  return {
    subject: message.subject,
    toCount: count(message.to),
    ccCount: count(message.cc),
    bccCount: count(message.bcc),
    hasHtml: Boolean(message.html),
    hasText: Boolean(message.text),
    attachmentCount: message.attachments?.length ?? 0,
    tagNames: message.tags?.map((t) => t.name) ?? [],
    metadataKeys: message.metadata ? Object.keys(message.metadata) : [],
  };
}

/** Emit redacted send/retry/error events to any logger, metrics, or tracer. */
export function observabilityPlugin(options: ObservabilityOptions): EmailPlugin {
  const redact = options.redactMessage ?? defaultRedact;

  async function emit(event: EmailObservabilityEvent): Promise<void> {
    await Promise.allSettled(
      [options.log, options.metric, options.trace].map(async (sink) => {
        if (!sink) return;
        try {
          await sink(event);
        } catch {
          // a broken sink must not mask a provider failure
        }
      }),
    );
  }

  return {
    id: options.id ?? "observability",
    async afterSend(event: AfterSendEvent) {
      await emit({
        type: "email.sent",
        provider: event.provider,
        attempt: event.attempt,
        metadata: event.options.metadata,
        message: redact(event.message),
        responseId: event.response.id,
        messageId: event.response.messageId,
      });
    },
    async onRetry(event: RetryEvent) {
      await emit({
        type: "email.retry",
        provider: event.provider,
        attempt: event.attempt,
        metadata: event.options.metadata,
        message: redact(event.message),
        nextAttempt: event.nextAttempt,
        delayMs: event.delayMs,
        error: { name: event.error.name, message: event.error.message },
      });
    },
    async onError(event: ErrorEvent) {
      await emit({
        type: "email.error",
        provider: event.provider,
        attempt: event.attempt,
        metadata: event.options.metadata,
        message: redact(event.message),
        error: { name: event.error.name, message: event.error.message },
      });
    },
  };
}

import type {
  AfterSendEvent,
  BeforeSendContext,
  EmailMessage,
  EmailPlugin,
  ErrorEvent,
  RetryEvent,
  SendResult,
} from "../types";

export type CaptureEvent =
  | { type: "beforeSend"; message: EmailMessage; metadata: Record<string, unknown> }
  | {
      type: "afterSend";
      provider: string;
      attempt: number;
      response: SendResult;
    }
  | {
      type: "retry";
      provider: string;
      attempt: number;
      nextAttempt: number;
      delayMs: number;
      error: Error;
    }
  | { type: "error"; provider: string; attempt: number; error: Error };

export interface EmailCaptureStore {
  readonly events: CaptureEvent[];
  clear(): void;
}

/** A capture store you can hold a reference to outside the client. */
export function createEmailCaptureStore(): EmailCaptureStore {
  const events: CaptureEvent[] = [];
  return {
    events,
    clear() {
      events.length = 0;
    },
  };
}

/**
 * Record the full (unredacted) send lifecycle into a store, for test
 * assertions. Pass a shared store from `createEmailCaptureStore()` to inspect
 * it directly, or omit it and read `plugin.store`.
 */
export function capturePlugin(
  store: EmailCaptureStore = createEmailCaptureStore(),
): EmailPlugin & { store: EmailCaptureStore } {
  return {
    id: "capture",
    store,
    beforeSend(ctx: BeforeSendContext): undefined {
      store.events.push({
        type: "beforeSend",
        message: ctx.message,
        metadata: ctx.options.metadata,
      });
      return undefined;
    },
    afterSend(event: AfterSendEvent) {
      store.events.push({
        type: "afterSend",
        provider: event.provider,
        attempt: event.attempt,
        response: event.response,
      });
    },
    onRetry(event: RetryEvent) {
      store.events.push({
        type: "retry",
        provider: event.provider,
        attempt: event.attempt,
        nextAttempt: event.nextAttempt,
        delayMs: event.delayMs,
        error: event.error,
      });
    },
    onError(event: ErrorEvent) {
      store.events.push({
        type: "error",
        provider: event.provider,
        attempt: event.attempt,
        error: event.error,
      });
    },
  };
}
